create table if not exists public.mow_crew_companies(id uuid primary key default gen_random_uuid(),owner_id uuid not null,name text not null check(length(name) between 1 and 120),created_at timestamptz not null default now());
create table if not exists public.mow_crew_members(company_id uuid not null references public.mow_crew_companies(id),user_id uuid not null,display_name text not null default 'Crew member',role text not null check(role in ('owner','lead','member')),primary key(company_id,user_id));
create table if not exists public.mow_crew_jobs(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.mow_crew_companies(id),assigned_to uuid,customer_name text not null,address text not null,city text not null default 'Palm Coast, FL',service_date date not null,scheduled_time time not null default '09:00',status text not null default 'scheduled' check(status in ('scheduled','arrived','in_progress','completed','blocked')),services text[] not null default array['Mow','Edge','Blow'],notes text not null default '',latitude double precision,longitude double precision,requires_photo boolean not null default true,customer_email text,customer_phone text,notification_consent boolean not null default false,arrived_at timestamptz,started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.mow_crew_events(id uuid primary key,company_id uuid not null references public.mow_crew_companies(id),job_id uuid not null references public.mow_crew_jobs(id),actor_id uuid not null,action text not null,payload jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists public.mow_crew_photos(id uuid primary key,company_id uuid not null references public.mow_crew_companies(id),job_id uuid not null references public.mow_crew_jobs(id),actor_id uuid not null,storage_path text not null unique,created_at timestamptz not null default now());
create table if not exists public.mow_crew_notifications(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.mow_crew_companies(id),job_id uuid not null references public.mow_crew_jobs(id),event_id uuid not null references public.mow_crew_events(id),channel text not null,body text not null,status text not null check(status in ('pending_provider','held_no_consent','held_no_contact','sent','failed')),created_at timestamptz not null default now(),unique(event_id));
create table if not exists public.mow_crew_messages(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.mow_crew_companies(id),actor_id uuid not null,body text not null check(length(body) between 1 and 2000),created_at timestamptz not null default now());
create index if not exists mow_crew_jobs_assignment on public.mow_crew_jobs(company_id,assigned_to,service_date);
create index if not exists mow_crew_events_job on public.mow_crew_events(job_id,created_at);
create index if not exists mow_crew_photos_job on public.mow_crew_photos(job_id);
create index if not exists mow_crew_messages_company on public.mow_crew_messages(company_id,created_at);
alter table public.mow_crew_companies enable row level security;
alter table public.mow_crew_members enable row level security;
alter table public.mow_crew_jobs enable row level security;
alter table public.mow_crew_events enable row level security;
alter table public.mow_crew_photos enable row level security;
alter table public.mow_crew_notifications enable row level security;
alter table public.mow_crew_messages enable row level security;
revoke all on public.mow_crew_companies,public.mow_crew_members,public.mow_crew_jobs,public.mow_crew_events,public.mow_crew_photos,public.mow_crew_notifications,public.mow_crew_messages from anon,authenticated;
grant all on public.mow_crew_companies,public.mow_crew_members,public.mow_crew_jobs,public.mow_crew_events,public.mow_crew_photos,public.mow_crew_notifications,public.mow_crew_messages to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('mow-crew-proof','mow-crew-proof',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create or replace function public.mow_crew_bootstrap(actor uuid,business_name text) returns uuid language plpgsql security invoker set search_path=public as $$declare cid uuid;begin select id into cid from mow_crew_companies where owner_id=actor order by created_at limit 1;if cid is not null then return cid;end if;insert into mow_crew_companies(owner_id,name) values(actor,business_name) returning id into cid;insert into mow_crew_members values(cid,actor,'Owner','owner');return cid;end$$;
create or replace function public.mow_crew_assign_member(actor uuid,cid uuid,member_email text,member_name text) returns uuid language plpgsql security invoker set search_path=public as $$declare uid uuid;begin if not exists(select 1 from mow_crew_members where company_id=cid and user_id=actor and role='owner') then raise exception 'Owner access required';end if;select id into uid from auth.users where lower(email)=lower(member_email) and email_confirmed_at is not null limit 1;if uid is null then raise exception 'Crew member must first create and verify their account';end if;insert into mow_crew_members values(cid,uid,member_name,'member') on conflict(company_id,user_id) do update set display_name=excluded.display_name;return uid;end$$;
create or replace function public.mow_crew_transition(actor uuid,jid uuid,eid uuid,verb text,details jsonb) returns jsonb language plpgsql security invoker set search_path=public as $$declare j mow_crew_jobs; r text;e mow_crew_events;n text;company_name text;begin select * into j from mow_crew_jobs where id=jid for update;if not found then raise exception 'Job unavailable';end if;select role into r from mow_crew_members where company_id=j.company_id and user_id=actor;if r is null or (r not in ('owner','lead') and j.assigned_to is distinct from actor) then raise exception 'Job access denied';end if;select * into e from mow_crew_events where id=eid;if found then if e.job_id<>jid or e.actor_id<>actor or e.action<>verb then raise exception 'Event conflict';end if;select status into n from mow_crew_notifications where event_id=eid;return jsonb_build_object('ok',true,'duplicate',true,'status',j.status,'notification_status',n);end if;
if verb='check_in' then if j.status not in ('scheduled','blocked') then raise exception 'Cannot check in from this job status';end if;j.status='arrived';j.arrived_at=coalesce(j.arrived_at,now());
elsif verb='start' then if j.status not in ('scheduled','arrived','blocked') then raise exception 'Job cannot be started';end if;j.status='in_progress';j.arrived_at=coalesce(j.arrived_at,now());j.started_at=coalesce(j.started_at,now());
elsif verb='complete' then if j.status<>'in_progress' then raise exception 'Start the job before completing it';end if;if not (to_jsonb(j.services) <@ coalesce(details->'completed_tasks','[]'::jsonb)) then raise exception 'Complete the service checklist';end if;if j.requires_photo and not exists(select 1 from mow_crew_photos where job_id=jid) then raise exception 'Add a completion photo';end if;j.status='completed';j.completed_at=now();
elsif verb='issue' then if j.status='completed' then raise exception 'Completed job cannot be blocked';end if;if length(coalesce(details->>'reason',''))<3 then raise exception 'Describe the issue';end if;j.status='blocked';else raise exception 'Unknown action';end if;
insert into mow_crew_events(id,company_id,job_id,actor_id,action,payload) values(eid,j.company_id,jid,actor,verb,details);update mow_crew_jobs set status=j.status,arrived_at=j.arrived_at,started_at=j.started_at,completed_at=j.completed_at,updated_at=now() where id=jid;
if verb in ('start','complete') then select name into company_name from mow_crew_companies where id=j.company_id;n=case when not j.notification_consent then 'held_no_consent' when coalesce(j.customer_email,'')='' and coalesce(j.customer_phone,'')='' then 'held_no_contact' else 'pending_provider' end;insert into mow_crew_notifications(company_id,job_id,event_id,channel,body,status) values(j.company_id,jid,eid,case when coalesce(j.customer_phone,'')<>'' then 'sms' else 'email' end,case when verb='start' then 'Good news—'||company_name||' is starting your lawn care at '||j.address||'. We’ll let you know when your yard is ready.' else 'Fresh cut. Clean edges. All handled. '||company_name||' has finished your lawn care at '||j.address||'. Your yard is ready to enjoy.' end,n);end if;return jsonb_build_object('ok',true,'status',j.status,'notification_status',n);end$$;
revoke all on function public.mow_crew_bootstrap(uuid,text),public.mow_crew_assign_member(uuid,uuid,text,text),public.mow_crew_transition(uuid,uuid,uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.mow_crew_bootstrap(uuid,text),public.mow_crew_assign_member(uuid,uuid,text,text),public.mow_crew_transition(uuid,uuid,uuid,text,jsonb) to service_role;
